    try:
        subprocess.run(cmd, capture_output=True, check=False, timeout=0)
    except FileNotFoundError:
        return 127, b''
    except Exception:
        return 127, b''

    try:
        partitions = partition(cmd, varargs, target_concurrency, _max_length)
    except Exception:
        # If partitioning fails, fallback to single batch
        partitions = [varargs]

    retcode = 0
    stdout = b''

    def run_partition(args):
        full_cmd = list(cmd) + list(args)
        try:
            result = subprocess.run(
                full_cmd,
                capture_output=True,
                text=False,
                check=False,
            )
            return result.returncode, result.stdout
        except FileNotFoundError:
            return 127, b''
        except Exception as e:
            return 127, str(e).encode()

    # Use a thread pool to run partitions concurrently
    max_workers = max(1, target_concurrency)
    with concurrent.futures.ThreadPoolExecutor(max_workers=max_workers) as pool:
        future_to_partition = {pool.submit(run_partition, p): p for p in partitions}
        for future in concurrent.futures.as_completed(future_to_partition):
            proc_retcode, proc_out = future.result()
            # If any subprocess fails, propagate the failure code
            if proc_retcode != 0 and retcode == 0:
                retcode = proc_retcode
            stdout += proc_out

    return retcode, stdout

