def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    coord_arr = np.asarray(coord)
    if coord_arr.ndim != 1 or coord_arr.size != len(self.edges):
        raise ValueError(
            f"coord must be a 1‑D array of length {len(self.edges)}, "
            f"got {coord_arr.shape}"
        )

    indices = []
    for dim, edge in enumerate(self.edges):
        bin_idx = np.searchsorted(edge, coord_arr[dim], side='right') - 1
        # Valid indices are 0 .. len(edge)-2
        if bin_idx < 0 or bin_idx >= (edge.size - 1):
            # Coordinate outside valid range; ignore this point
            return
        indices.append(bin_idx)

    try:
        self.values[tuple(indices)] += weight
    except Exception as exc:
        raise RuntimeError(f"Failed to fill histogram: {exc}") from exc

