        if new_num < 10 ** width:
            new_last = f"{new_num:0{width}d}"
        else:
            new_last = str(new_num)
        parts[-1] = new_last
        return ".".join(parts)
    except Exception:
        # fallback: simple int increment if whole string is numeric
        try:
            num = int(version)
            return str(num + 1)
        except Exception:
            return ""

def next_version(version):
    """Next version identifier following existing pattern.

