def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root'    - looks like an OCFL Storage Root
        'object'  - looks like an OCFL Object
        'file'    - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os

    try:
        if not os.path.exists(path):
            return f"Path does not exist: {path!r}"
        if os.path.isfile(path):
            return "file"

        if not os.path.isdir(path):
            return f"Path is not a file or directory: {path!r}"

        # Find files that start with '0=' (Namaste files)
        namaste_files = [f for f in os.listdir(path) if f.startswith("0=")]
        if not namaste_files:
            return "No Namaste file found"

        # If multiple Namaste files, pick the first but note ambiguity
        if len(namaste_files) > 1:
            # Attempt to determine type from each; if they disagree, return ambiguous
            types = set()
            for nf in namaste_files:
                full = os.path.join(path, nf)
                if not os.path.isfile(full):
                    continue
                try:
                    with open(full, "r", encoding="utf-8", errors="ignore") as fh:
                        first_line = fh.readline().strip().lower()
                    if "root" in first_line:
                        types.add("root")
                    elif "object" in first_line:
                        types.add("object")
                except Exception as e:
                    continue
            if len(types) == 1:
                return types.pop()
            elif len(types) == 0:
                return "Namaste files present but no identifiable type"
            else:
                return "Ambiguous Namaste types found"
        else:
            # Single Namaste file
            full = os.path.join(path, namaste_files[0])
            try:
                with open(full, "r", encoding="utf-8", errors="ignore") as fh:
                    first_line = fh.readline().strip().lower()
                if "root" in first_line:
                    return "root"
                if "object" in first_line:
                    return "object"
                # If it has neither, we cannot determine
                return "Namaste file found but type unknown"
            except Exception as e:
