def parse_frequency(frequency):
    """
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    """
    # Handle None or "always" (case-insensitive)
    if frequency is None:
        return None
    if not isinstance(frequency, str):
        raise ValueError("frequency must be a string or None")
    trimmed = frequency.strip()
    if trimmed.lower() == "always":
        return None
    if trimmed == "":
        raise ValueError("empty frequency string")

    # Split into numeric and unit parts
    parts = trimmed.split()
    if len(parts) != 2:
        raise ValueError(f"invalid frequency format: '{frequency}'")
    num_part, unit_part = parts
    try:
        quantity = int(num_part)
    except ValueError:
        raise ValueError(f"invalid numeric value in frequency: '{num_part}'")

    unit = unit_part.lower()
    # Normalize unit (accept plurals and abbreviations)
    if unit in {"year", "years"}:
        return datetime.timedelta(days=quantity * 365)
    if unit in {"month", "months"}:
        return datetime.timedelta(days=quantity * 30)
    if unit in {"week", "weeks"}:
        return datetime.timedelta(weeks=quantity)
    if unit in {"day", "days"}:
        return datetime.timedelta(days=quantity)
    if unit in {"hour", "hours"}:
        return datetime.timedelta(hours=quantity)
    if unit in {"minute", "minutes", "min"}:
        return datetime.timedelta(minutes=quantity)
    if unit in {"second", "seconds", "sec"}:
        return datetime.timedelta(seconds=quantity)

    raise ValueError(f"unknown time unit in frequency: '{unit_part}'")

