def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type)."""
    if seq is None:
        raise ValueError("No sequence provided")

    # Handle string or bytes (sequence content)
    if isinstance(seq, (str, bytes)):
        sequence = seq.decode() if isinstance(seq, bytes) else seq
        seq_type = "string"
        return sequence, seq_type

    # Handle already-sequence types like list, tuple, set, bytearray
    if isinstance(seq, (list, tuple, set, bytearray)):
        sequence = seq
        seq_type = type(seq).__name__
        return sequence, seq_type

    # Handle file-like objects
    if hasattr(seq, "read"):
        try:
            parts = []
            if bufsize:
                while True:
                    chunk = seq.read(bufsize)
                    if not chunk:
                        break
                    parts.append(chunk)
            else:
                parts.append(seq.read())
            raw = "".join(parts)
            sequence = raw
            seq_type = "file"
            return sequence, seq_type
        except Exception as exc:
            raise ValueError(f"Unable to read sequence from file-like object {seq!r}: {exc}") from exc

    # Handle generic iterables / generators
    try:
        # Consume iterable into a string
        sequence = "".join(list(seq))
        seq_type = "iterator"
        return sequence, seq_type
    except Exception as exc:
        raise ValueError(f"Unable to derive sequence from iterable {seq!r}: {exc}") from exc

def scale(self, other=None):
        """Get or set the scale of the graph.

        If *other* is ``None``, return the scale of this graph.

        If a numeric *other* is provided, rescale to that value.
        If the graph has unknown or zero scale,
        rescaling that will raise :exc:`~.LenaValueError`.

        To get meaningful results, graph's fields are used.
        Only the last coordinate is rescaled.
        For example, if the graph has *x* and *y* coordinates,
        then *y* will be rescaled, and for a 3-dimensional graph
        *z* will be rescaled.
        All errors are rescaled together with their coordinate.
        """
        # Return current scale if no other provided
        if other is None:
            return getattr(self, "_scale", None)

        # Validate numeric input
        try:
            target_scale = float(other)
        except Exception:
            raise TypeError("Scale must be a numeric value")

        # Current scale must exist and be non-zero
        current_scale = getattr(self, "_scale", None)
        if current_scale is None or current_scale == 0:
            raise ValueError(
                "Cannot rescale graph with unknown or zero current scale"
            )

        # Compute scaling factor
        factor = target_scale / current_scale

        # Rescale last coordinate and its associated error if they exist
        # Expect that coordinate arrays are stored in a list or tuple
        # named `coordinates` and associated errors in `errors`.
        coordinates = getattr(self, "coordinates", None)
        errors = getattr(self, "errors", None)

        # Apply factor to last coordinate
        if coordinates and isinstance(coordinates, (list, tuple)):
            try:
                coordinates[-1] = coordinates[-1] * factor
            except Exception:
                # If coordinates are not Numpy arrays, try generic iteration
                try:
                    coordinates[-1] = [v * factor for v in coordinates[-1]]
                except Exception:
                    pass  # Leave unchanged if not multiplicative

        # Rescale corresponding errors if present
        if errors and isinstance(errors, (list, tuple)):
            try:
                errors[-1] = errors[-1] * abs(factor)
            except Exception:
                try:
                    errors[-1] = [e * abs(factor) for e in errors[-1]]
                except Exception:
                    pass  # Leave unchanged if not multiplicative

        # Update the graph's scale attribute
        self._scale = target_scale
        return None"

