        host = handle.split("@")[1]
    except Exception:
        return None

    # Build the RFC7033 webfinger URL
    url = "https://{0}/.well-known/webfinger?resource=acct:{1}".format(host, handle)

    # Attempt retrieval over HTTPS
    try:
        page = urllib2.urlopen(url)
    except Exception:
        # Fallback to HTTP if HTTPS fails
        alt_url = "http://{0}/.well-known/webfinger?resource=acct:{1}".format(host, handle)
        try:
            page = urllib2.urlopen(alt_url)
        except Exception:
            return None
    else:
        pass

    # Read and return the document
    try:
        data = page.read()
        if isinstance(data, bytes):
            data = data.decode("utf-8", errors="ignore")
        return data
    except Exception:
        return None
    finally:
        try:
            page.close()
        except Exception:
            pass

