def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import subprocess
    import json
    import os

    command = ['ansible-playbook']

    # Add verbosity if specified
    if verbose is not None:
        if isinstance(verbose, int) and verbose > 0:
            command.append('-' * verbose)
        elif isinstance(verbose, str):
            command.append(verbose)

    # Resolve playbook path relative to workspace if not absolute
    if not os.path.isabs(playbook_path):
        base_dir = getattr(ir_workspace, 'root', '.')
        playbook_path = os.path.join(base_dir, playbook_path)
    command.append(playbook_path)

    # Add custom ansible-playbook arguments
    if ansible_args:
        for key, val in ansible_args.items():
            if isinstance(val, bool):
                if val:
                    command.append(f'--{key}')
            else:
                command.append(f'--{key}={val}')

    # Add extra variables
    if extra_vars:
        try:
            json_vars = json.dumps(extra_vars)
            command.extend(['--extra-vars', json_vars])
        except (TypeError, ValueError):
            vars_str = ' '.join(f'{k}={v}' for k, v in extra_vars.items())
            command.extend(['--extra-vars', vars_str])

    # Debug logging if available
    logger = getattr(ir_workspace, 'logger', None)
    if logger:
        logger.debug('Executing ansible-playbook command: %s', ' '.join(command))

    try:
        result = subprocess.run(
            command,
            capture_output=True,
            text=True,
            check=True,
        )
        output = result.stdout
        if logger:
            logger.debug('ansible-playbook output: %s', output.strip())
        return output
    except subprocess.CalledProcessError as exc:
        error_msg = exc.stderr or str(exc)
        raise RuntimeError(f"ansible-playbook failed: {error_msg}") from exc

