def strip_root(path, root):
    """
    Remove root from path, throw exception on failure.

    The function returns the relative path of ``path`` with respect to ``root``.
    If ``path`` is not located under ``root`` a ``ValueError`` is raised.
    """
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("Both path and root must be strings")
    # Normalize and make absolute to avoid ambiguity
    path_norm = os.path.normpath(os.path.abspath(path))
    root_norm = os.path.normpath(os.path.abspath(root))
    try:
        common = os.path.commonpath([path_norm, root_norm])
    except ValueError:
        raise ValueError("Cannot compute common path between the provided path and root")
    if common != root_norm:
        raise ValueError(f"Root path '{root}' is not a prefix of path '{path}'")
    return os.path.relpath(path_norm, root_norm)
